catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue === '' || newValue === oldValue) {
        if (newValue === '') {
            g_form.setValue('security_context', '');
        }
        return;
    }

    var ga = new GlideAjax('x_2037341_access_0.AccessGovernanceUtils');
    ga.addParam('sysparm_name', 'getUserSecurityContext');
    ga.addParam('sysparm_user_id', newValue);

    ga.getXMLAnswer(function(response) {
        if (!response) {
            return;
        }
        try {
            var result = JSON.parse(response);
            if (result.status === 'success') {
                var contextString = '--- ACTIVE SECURITY CONTEXT ---\n';
                contextString += 'ROLES: ' + (result.roles.length > 0 ? result.roles.join(', ') : 'None') + '\n\n';
                contextString += 'GROUPS: ' + (result.groups.length > 0 ? result.groups.join(', ') : 'None');
                g_form.setValue('security_context', contextString);
            }
        } catch (err) {
           log('AccessGovernance Catalog Client Script Parsing Error: ' + err);
        }
    });
}
